const audioBase64 = $input.item.binary?.data?.data;

if (!audioBase64) {
  throw new Error('Download audio Telegram fallito: nessun dato binario ricevuto');
}

return {
  json: {
    requestBody: {
      contents: [{
        parts: [
          {
            text: "Trascrivi fedelmente in italiano il contenuto del seguente messaggio vocale di un paziente di uno studio medico. Restituisci SOLO la trascrizione, senza commenti aggiuntivi. Se l'audio è incomprensibile, troppo breve, silenzioso o non contiene parlato chiaro, rispondi ESATTAMENTE e solo con la stringa: AUDIO_NON_COMPRENSIBILE"
          },
          {
            inline_data: { mime_type: 'audio/ogg', data: audioBase64 }
          }
        ]
      }]
    }
  }
};

const res = $input.item.json;
const text = (res?.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
const isInvalid = !text || /AUDIO_NON_COMPRENSIBILE/i.test(text) || text.length < 2;

const original = $('Telegram Trigger1').item.json;

return {
  json: {
    ...original,
    message: {
      ...original.message,
      text: isInvalid ? '' : text
    },
    _voiceTranscribed: true,
    _voiceValid: !isInvalid
  }
};

const msg = $input.item.json;

const chatId = String(
  msg?.message?.chat?.id ??
  msg?.callback_query?.message?.chat?.id ??
  ''
);
const text = (
  msg?.message?.text ??
  msg?.callback_query?.data ??
  ''
).trim();
const firstName = msg?.message?.from?.first_name ?? '';
const lastName  = msg?.message?.from?.last_name  ?? '';
const timestamp = new Date().toISOString();
const inputType = msg?._voiceTranscribed ? 'AUDIO' : 'TESTO';

if (!chatId || !text) {
  throw new Error('Messaggio non valido: chatId o testo mancante');
}

return {
  json: {
    chatId,
    text,
    firstName,
    lastName,
    timestamp,
    sessionKey: `sess_${chatId}`,
    inputType
  }
};

// Legge la KB dal foglio KB_CACHE e i dati del messaggio
const sheetData = $('Get row(s) in sheet').first().json;
const kb = sheetData?.kbContent || 'Nessuna knowledge base disponibile.';
const msgData = $('02 · Estrai Dati Messaggio').item.json;

return {
  json: {
    chatId: msgData.chatId,
    text: msgData.text,
    firstName: msgData.firstName,
    lastName: msgData.lastName,
    timestamp: msgData.timestamp,
    sessionKey: msgData.sessionKey,
    inputType: msgData.inputType,
    knowledgeBase: kb
  }
};

const ALLOWED_URGENZA = ['ROSSO', 'GIALLO', 'VERDE'];

const content = $input.item.json?.output ?? '';

// Cerca SOLO il primo blocco ticket: eventuali blocchi ulteriori (tentativo di injection
// con più <<<TICKET_START>>> annidati nel messaggio del paziente) vengono ignorati.
const ticketMatch = content.match(/<<<TICKET_START>>>([\s\S]*?)<<<TICKET_END>>>/);
let ticket = null;
let replyText = content;
let validationFlag = null;

if (ticketMatch) {
  const raw = ticketMatch[1].trim();
  ticket = {};
  for (const line of raw.split('\n').filter(l => l.includes(':'))) {
    const idx = line.indexOf(':');
    const key = line.substring(0, idx).trim().toUpperCase();
    // Anti-injection: tronca ogni campo a 500 caratteri, non fidarsi della lunghezza prodotta dal modello
    const val = line.substring(idx + 1).trim().substring(0, 500);
    ticket[key] = val;
  }

  // VALIDAZIONE LATO CODICE (non solo lato LLM): l'urgenza deve essere uno dei 3 valori ammessi.
  // Se il modello (o un tentativo di prompt injection) produce un valore diverso, NON ci fidiamo:
  // declassiamo cautelativamente a GIALLO (mai a VERDE) per forzare una revisione umana.
  let urg = (ticket.URGENZA || '').toUpperCase().trim();
  if (!ALLOWED_URGENZA.includes(urg)) {
    validationFlag = `Urgenza non valida ricevuta ("${ticket.URGENZA || 'vuota'}") - declassata cautelativamente a GIALLO per revisione manuale.`;
    urg = 'GIALLO';
  }
  ticket.urgenzaLevel = urg;

  // Rimuovi dalla risposta visibile al paziente QUALSIASI blocco ticket, incluso il rumore extra
  replyText = content.replace(/<<<TICKET_START>>>[\s\S]*?<<<TICKET_END>>>/g, '').trim();
}

const msgData = $('02 · Estrai Dati Messaggio').item.json;

return {
  json: {
    replyText,
    hasTicket: !!ticket,
    ticket,
    validationFlag,
    chatId: msgData.chatId,
    timestamp: msgData.timestamp,
    claudeRaw: content
  }
};

const error = $input.item.json;
console.error('[SecretarIA] Errore workflow:', JSON.stringify(error));

let chatId = null;
try {
  chatId = $('02 · Estrai Dati Messaggio').item?.json?.chatId ?? null;
} catch (e) {
  // Il nodo 02 potrebbe non essere ancora stato eseguito in questo branch (es. errore durante la trascrizione audio)
}
if (!chatId) {
  try {
    chatId = $('Telegram Trigger1').item?.json?.message?.chat?.id ?? null;
  } catch (e) {}
}

return {
  json: {
    chatId,
    errorMessage: 'Mi dispiace, al momento non riesco a risponderti per un problema tecnico. La preghiamo di contattare lo studio direttamente al numero +41 91 XXX XX XX, oppure di riprovare tra qualche minuto.'
  }
};
